namespace App.Infrastructure.Repositories;
public sealed class EfReviewRepository
{
    public async Task ApproveAsync(Entry entry)
    {
        entry.ReviewStatus = ReviewStatus.Approved;
        await _db.SaveChangesAsync();
    }
}

namespace App.Infrastructure.Repositories;
public sealed class EfEntryRepository
{
    public Task UpdateAsync(Entry entry) { _db.Update(entry); return _db.SaveChangesAsync(); }
    public bool IsDone(Entry e) => e.ReviewStatus == ReviewStatus.Done;
    public object Project(Entry e) => new { Status = e.ReviewStatus };
}

namespace App.Infrastructure.Repositories;
public sealed class EfTaskRepository
{
    // 以前这里写过 task.RunStatus = Done，已挪到应用服务
    private const string Note = "task.RunStatus = x";
    public void Mark(BackgroundTask task) { this.task.RunStatus = RunStatus.Done; }
}

namespace App.Application.Services;
public sealed class ReviewService
{
    public void Approve(Entry entry) { entry.ReviewStatus = ReviewStatus.Approved; }
}

namespace App.Infrastructure.Repositories;
public sealed class EfOrderRepository
{
    public Task<List<Order>> FindApprovedAsync() => _db.Orders.Where(o => o.Status != OrderStatus.Draft).ToListAsync();
}
